import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem111 preserva dados operacionais',()=>{for(const [n,titulo,expected,link] of [["6794388344","Celular Samsung Galaxy A37 5G 128GB, 6GB RAM","Celular Samsung Galaxy A37 5G 128GB, 6GB RAM","https://www.mercadolivre.com.br/p/MLB68206703?wid=MLB6794388344"],["6837462690","Tênis Masculino Esportivo Corrida Leve Confortável Macio","Tênis esportivo masculino Ravero","https://produto.mercadolivre.com.br/MLB-6837462690-tnis-masculino-esportivo-corrida-leve-confortavel-macio-_JM?searchVariation=202668186919"],["6918814082","Kit Gamer Mageon Mobilador Teclado Qwerty + Mouse 1200 Dpi Preto","Kit Gamer Mageon Mobilador Teclado Qwerty + Mouse 1200 Dpi Preto","https://www.mercadolivre.com.br/up/MLBU4723609338?pdp_filters=item_id%3AMLB7407693118"]]){const p={id:'mlMLB'+n,titulo,link,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);for(const k of ['id','preco','linkAfiliado','link'])assert.equal(x[k],p[k]);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);}});
